css:
.hr-page{--ink:#17202a;--blue:#2563eb;--deep:#1e40af;--tint:#eef3ff;--mute:#5b6675;--line:#dde3ec;max-width:1080px;margin:0 auto;padding:0 24px 96px;background:#fff;color:var(--ink);font-family:var(--page-sans),'Pretendard','Apple SD Gothic Neo','Noto Sans KR',sans-serif;font-size:17px;line-height:1.75;word-break:keep-all;overflow-wrap:break-word;font-variant-numeric:tabular-nums;box-sizing:border-box;overflow-x:hidden}
.hr-page *,.hr-page *::before,.hr-page *::after{box-sizing:border-box}
.hr-page h1,.hr-page h2,.hr-page h3,.hr-page p,.hr-page dl,.hr-page dd,.hr-page ul,.hr-page ol,.hr-page figure{margin:0;padding:0}
.hr-page ul,.hr-page ol{list-style:none}
.hr-hero{padding:72px 0 56px}
.hr-who{font-size:16px;color:var(--mute);margin-bottom:20px}
.hr-who strong{color:var(--ink);font-weight:700;margin-right:10px}
.hr-hero h1{font-size:clamp(34px,6.4vw,60px);line-height:1.18;font-weight:800;letter-spacing:-.03em;max-width:14em}
.hr-lede{margin-top:24px;max-width:38em;color:#2c3744}
.hr-lcp{margin-top:44px;padding:28px 28px 20px;background:var(--tint);border-radius:6px}
.hr-lcp figcaption{font-weight:700;font-size:15px;margin-bottom:18px}
.hr-lcp figcaption span{font-weight:500;color:var(--mute);margin-left:10px}
.hr-lcp-row{display:grid;grid-template-columns:64px 1fr 76px;align-items:center;gap:14px;margin-bottom:12px}
.hr-lcp-name{font-size:14px;color:var(--mute)}
.hr-lcp-track{display:block;height:36px;position:relative}
.hr-lcp-bar{display:block;height:100%;transform-origin:left center;animation:hr-grow 1.1s cubic-bezier(.2,.7,.2,1) both}
.hr-lcp-bar.is-before{width:95%;background:#b9c3d3}
.hr-lcp-bar.is-after{width:47.5%;background:var(--blue);animation-delay:.5s}
.hr-lcp-val{font-size:26px;font-weight:800;text-align:right;letter-spacing:-.02em}
.hr-lcp-val.is-after{color:var(--deep)}
.hr-axis{display:grid;grid-template-columns:repeat(5,1fr);margin:6px 90px 0 78px;font-size:12px;color:var(--mute);border-top:1px solid #c5d0e6;padding-top:4px}
.hr-axis span:last-child{text-align:right}
.hr-axis span:not(:first-child):not(:last-child){text-align:center}
@keyframes hr-grow{from{transform:scaleX(0)}to{transform:scaleX(1)}}
.hr-strip{display:grid;grid-template-columns:1fr 1fr;gap:0;margin-top:28px;border-top:1px solid var(--line)}
.hr-strip>div{padding:18px 20px 0 0}
.hr-strip>div+div{padding-left:24px;border-left:1px solid var(--line)}
.hr-strip dt{font-size:14px;color:var(--mute);line-height:1.5}
.hr-strip dd{font-size:28px;font-weight:700;letter-spacing:-.02em;margin-top:4px;color:var(--mute)}
.hr-strip dd em{font-style:normal;color:var(--deep);font-weight:800}
.hr-strip dd b{color:var(--blue);font-weight:600;margin:0 4px}
.hr-sec{padding:72px 0 8px;border-top:1px solid var(--line)}
.hr-sec h2{font-size:clamp(24px,4vw,34px);line-height:1.3;font-weight:800;letter-spacing:-.025em;max-width:20em}
.hr-sub{margin-top:12px;color:var(--mute);max-width:36em}
.hr-period{font-size:14px;color:var(--blue);font-weight:600;margin-bottom:8px;line-height:1.4}
.hr-nums{margin-top:36px;display:grid;grid-template-columns:1fr 1fr;gap:0 48px}
.hr-nums li{padding:20px 0 24px;border-top:1px solid var(--line)}
.hr-nums-head{display:flex;flex-direction:column;gap:2px}
.hr-nums-k{font-weight:700;line-height:1.4}
.hr-nums-src{font-size:13px;color:var(--mute);line-height:1.4}
.hr-nums-v{display:flex;align-items:baseline;gap:12px;margin-top:10px}
.hr-nums-v s{font-size:20px;color:var(--mute);text-decoration:none;position:relative}
.hr-nums-v s::after{content:'→';margin-left:12px;color:var(--blue)}
.hr-nums-v b{font-size:36px;font-weight:800;color:var(--deep);letter-spacing:-.03em}
.hr-rel{margin-top:12px}
.hr-rel-b,.hr-rel-a{display:block;height:8px;margin-bottom:5px}
.hr-rel-b{background:#cdd5e2}
.hr-rel-a{background:var(--blue)}
.hr-case{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,6fr);gap:48px}
.hr-case-head .hr-pair{margin-top:20px;display:flex;flex-direction:column;line-height:1.3}
.hr-case-head .hr-pair+.hr-pair{margin-top:12px}
.hr-pair b{font-size:28px;font-weight:800;color:var(--deep);letter-spacing:-.02em}
.hr-pair span{font-size:14px;color:var(--mute)}
.hr-dl>div{display:grid;grid-template-columns:92px 1fr;gap:16px;padding:16px 0;border-top:1px solid var(--line)}
.hr-dl>div:first-child{border-top:0;padding-top:4px}
.hr-dl dt{font-weight:700;color:var(--deep)}
.hr-steps{margin-top:36px;display:grid;grid-template-columns:repeat(4,1fr);gap:20px;counter-reset:s}
.hr-steps li{position:relative;padding-top:0}
.hr-step-n{display:flex;align-items:center;justify-content:center;width:32px;height:32px;border-radius:50%;background:var(--blue);color:#fff;font-weight:700;font-size:15px;position:relative;z-index:1}
.hr-steps li:not(:last-child)::before{content:'';position:absolute;left:32px;right:-20px;top:15px;height:2px;background:#bcd0fb}
.hr-steps h3{margin-top:14px;font-size:18px;font-weight:700}
.hr-steps p{margin-top:6px;font-size:15px;line-height:1.65;color:#2c3744}
.hr-result{margin-top:32px;padding:18px 22px;background:var(--tint);border-left:4px solid var(--blue);max-width:44em}
.hr-result b{color:var(--deep);font-weight:800}
.hr-a11y{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,6fr);gap:48px;align-items:center}
.hr-a11y-text>p:last-child{margin-top:16px;max-width:30em}
.hr-tiles{display:grid;grid-template-columns:repeat(8,1fr);gap:8px}
.hr-tiles i{display:block;aspect-ratio:1/1;background:var(--tint);border:1px solid #c9d8fb;border-radius:4px;position:relative}
.hr-tiles i::after{content:'';position:absolute;left:34%;top:20%;width:24%;height:42%;border:solid var(--blue);border-width:0 3px 3px 0;transform:rotate(45deg)}
.hr-tools{margin-top:28px}
.hr-tools>div{display:grid;grid-template-columns:180px 1fr;gap:20px;padding:16px 0;border-top:1px solid var(--line)}
.hr-tools dt{font-weight:700}
.hr-make{margin-top:28px;display:grid;grid-template-columns:1fr 1fr;gap:48px}
.hr-make h3,.hr-job h3{font-size:19px;font-weight:700;line-height:1.4}
.hr-make p{margin-top:8px}
.hr-make article{border-top:2px solid var(--blue);padding-top:16px}
.hr-job{display:grid;grid-template-columns:150px 1fr;gap:24px;margin-top:24px}
.hr-job .hr-period{margin:4px 0 0}
.hr-job p{margin-top:8px;max-width:40em}
.hr-ev{margin-top:24px}
.hr-ev li{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr);column-gap:32px;padding:16px 0;border-top:1px solid var(--line)}
.hr-ev b{font-weight:700;line-height:1.5}
.hr-ev span{grid-column:1;font-size:13px;color:var(--blue);font-weight:600;line-height:1.5}
.hr-ev p{grid-column:2;grid-row:1/3;font-size:15px;line-height:1.7;color:#2c3744}
@media (max-width:760px){
.hr-page{padding:0 18px 72px;font-size:16px}
.hr-hero{padding:44px 0 40px}
.hr-lcp{padding:20px 16px 14px}
.hr-lcp-row{grid-template-columns:48px 1fr 60px;gap:8px}
.hr-lcp-name{font-size:12px}
.hr-lcp-val{font-size:20px}
.hr-axis{margin:6px 68px 0 56px;font-size:11px}
.hr-strip{grid-template-columns:1fr}
.hr-strip>div+div{padding-left:0;border-left:0;border-top:1px solid var(--line);margin-top:16px}
.hr-sec{padding-top:52px}
.hr-nums{grid-template-columns:1fr}
.hr-case,.hr-a11y,.hr-make{grid-template-columns:1fr;gap:28px}
.hr-dl>div{grid-template-columns:1fr;gap:4px}
.hr-steps{grid-template-columns:1fr;gap:0}
.hr-steps li{padding:0 0 24px 48px}
.hr-step-n{position:absolute;left:0;top:0}
.hr-steps h3{margin-top:2px}
.hr-steps li:not(:last-child)::before{left:15px;right:auto;top:32px;bottom:0;width:2px;height:auto}
.hr-tiles{grid-template-columns:repeat(6,1fr)}
.hr-tools>div,.hr-job{grid-template-columns:1fr;gap:4px}
.hr-ev li{grid-template-columns:1fr}
.hr-ev p{grid-column:1;grid-row:auto;margin-top:6px}
}
@media (prefers-reduced-motion:reduce){.hr-lcp-bar{animation:none}}
